select g.id, g.seller_id as sellerId, g.category_id as categoryId, c.name as categoryName, g.title, g.price, g.old_price as oldPrice, g.quality, g.location, g.status, as statusDesc, g.cover, g.view_count as viewCount, g.favorite_count as favoriteCount, u.name as sellerName, u.avatar as sellerAvatar, g.publish_time as publishTime from goods g left join category c on g.category_id = c.id left join user u on g.seller_id = u.id
g.status = 3
and g.category_id = #{categoryId}
and g.seller_id = #{sellerId}
and g.price >= #{minPrice}
and g.price <= #{maxPrice}
and ( g.title like concat('%', #{keyword}, '%') or g.detail like concat('%', #{keyword}, '%') or c.name like concat('%', #{keyword}, '%') )
order by g.publish_time desc, g.id desc

select g.id, g.seller_id as sellerId, g.category_id as categoryId, c.name as categoryName, g.title, g.detail, g.price, g.old_price as oldPrice, g.quality, g.location, g.status, as statusDesc, g.cover, g.reason, g.view_count as viewCount, g.favorite_count as favoriteCount, g.publish_time as publishTime, g.update_time as updateTime from goods g left join category c on g.category_id = c.id
g.seller_id = #{sellerId}
and g.status = #{dto.status}
and g.category_id = #{dto.categoryId}
and g.price >= #{dto.minPrice}
and g.price <= #{dto.maxPrice}
and ( g.title like concat('%', #{dto.keyword}, '%') or g.detail like concat('%', #{dto.keyword}, '%') or c.name like concat('%', #{dto.keyword}, '%') )
order by g.update_time desc, g.id desc

select g.id, g.seller_id as sellerId, u.name as sellerName, u.student_no as sellerStudentNo, g.category_id as categoryId, c.name as categoryName, g.title, g.price, g.old_price as oldPrice, g.quality, g.location, g.status, as statusDesc, g.cover, g.reason, g.audit_time as auditTime, g.publish_time as publishTime, g.update_time as updateTime from goods g left join category c on g.category_id = c.id left join user u on g.seller_id = u.id
and g.status = #{status}
and g.category_id = #{categoryId}
and g.seller_id = #{sellerId}
and g.price >= #{minPrice}
and g.price <= #{maxPrice}
and ( g.title like concat('%', #{keyword}, '%') or g.detail like concat('%', #{keyword}, '%') or c.name like concat('%', #{keyword}, '%') or u.name like concat('%', #{keyword}, '%') or u.student_no like concat('%', #{keyword}, '%') )
order by case when g.status = 1 then 0 else 1 end, g.update_time desc, g.id desc
